import { loadSchema, activeSchemaHash, jackpotBattleKey } from './schema.js';
import { contractInterface, compareLogs, logKey, ChainDataError, decodeLog, checkAbort } from './client.js';
import { cachedLogs } from './event-store.js';
import { bigintJSON } from './state.js';

// jackpotBattleKey() is CRAPS itself from audit 0889affc1 on, so the list is deduplicated.
const sources = () => [...new Set(['GAME', 'ADMIN', 'COIN', 'COINFLIP', 'CRAPS', 'QUESTS', 'AFFILIATE', 'JACKPOTS', 'PARIMUTUEL', 'WWXRP', 'SDGNRS', 'DGNRS', 'GNRUS', 'VAULT', 'DEITY_PASS', jackpotBattleKey()])];
const catalogs = new Map();
export async function eventCatalog() {
  const hash = activeSchemaHash();
  if (!catalogs.has(hash)) catalogs.set(hash, Promise.all(sources().map(async contract => (await loadSchema(contract)).abi
    .filter(event => event.type === 'event' && !event.anonymous).map(event => ({ contract, event })))).then(rows => rows.flat()));
  return catalogs.get(hash);
}
export function plainEvent(log, fragment) {
  return { name: fragment.name, args: Object.fromEntries(fragment.inputs.map((input, i) => {
    const raw = log.args[i];
    return [input.name, input.type === 'address' ? raw.toLowerCase() : typeof raw === 'bigint' ? String(raw) : raw];
  })), blockNumber: log.blockNumber, blockHash: log.blockHash, logIndex: log.logIndex, transactionIndex: log.transactionIndex,
  transactionHash: log.transactionHash };
}
export async function eventFacts(s, names, { contract, player, day, fromBlock, toBlock, signal, filters = {} } = {}) {
  // `contract` may name one source or several (the daily jackpot's far-future leg is logged by
  // COIN_DRAW_BATTLE, next to the Game's own award events).
  const contracts = contract == null ? null : [].concat(contract);
  const requested = new Set(names); const catalogRows = (await eventCatalog()).filter(row => requested.has(row.event.name) && (!contracts || contracts.includes(row.contract)));
  const known = new Set(catalogRows.map(row => row.event.name));
  const missing = names.filter(name => !known.has(name));
  if (missing.length) throw new ChainDataError('Unknown contract events: ' + missing.join(', '), 'UNSUPPORTED_READ');
  const groups = new Map();
  for (const { contract: source, event } of catalogRows) {
    const iface = await contractInterface(source);
    // An event may have more than one indexed player (owner/operator, payer/
    // recipient). Query each relevant position and deduplicate by log identity.
    const playerFields = player ? event.inputs.filter(input => input.indexed && input.type === 'address') : [null];
    if (player && !playerFields.length) throw new ChainDataError(`${event.name} has no player topic.`, 'UNSUPPORTED_READ');
    for (const field of playerFields) {
      const values = { ...filters, ...(day == null ? {} : { day }), ...(field ? { [field.name]: player } : {}) };
      const topics = iface.encodeFilterTopics(event.name, event.inputs.map(input => input.indexed ? values[input.name] ?? null : null));
      const key = JSON.stringify([source, topics.slice(1)]);
      if (!groups.has(key)) groups.set(key, { source, topics: [[], ...topics.slice(1)], iface });
      groups.get(key).topics[0].push(topics[0]);
    }
  }
  const results = [];
  // Each group occupies the shared log lane, with at most three RPCs active.
  for (const { source, topics, iface } of groups.values()) {
    const logs = await cachedLogs(s, { address: s.client.address(source), topics }, { fromBlock, toBlock, signal });
    const now = () => globalThis.performance?.now?.() ?? Date.now();
    let sliceStarted = now(), decoded = 0;
    for (const log of logs) {
      // Cold caches can decode hundreds of ABI events in one microtask. Keep
      // the exact snapshot/results, but let input and paint run between slices.
      if (decoded++ % 16 === 0 && now() - sliceStarted >= 8) {
        await new Promise(resolve => setTimeout(resolve, 0));
        checkAbort(signal);
        sliceStarted = now();
      }
      const parsed = decodeLog(iface, log); if (!parsed) continue;
      const row = plainEvent({ ...log, args: parsed.args }, parsed.fragment);
      if (day != null && row.args.day != null && Number(row.args.day) !== Number(day)) continue;
      if (Object.entries(filters).some(([key, value]) => row.args[key] != null && !(Array.isArray(value) ? value : [value]).some(item => String(row.args[key]).toLowerCase() === String(item).toLowerCase()))) continue;
      results.push(row);
    }
  }
  return [...new Map(results.map(row => [`${row.name}:${logKey(row)}`, row])).values()].sort(compareLogs);
}

// A cold history page has a bounded amount of RPC work. Its cursor also moves
// across empty ranges, so a wallet with no recent activity can ask for older
// history without scanning the entire age of the game during dashboard boot.
export async function eventPage(s, names, url, { extra, ...options } = {}) {
  const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit') || 50)));
  const before = Number(url.searchParams.get('before') || Number.MAX_SAFE_INTEGER);
  if (!Number.isSafeInteger(before) || before < 1 || !Number.isInteger(limit)) throw new ChainDataError('Invalid history cursor.', 'INVALID_REQUEST');
  let end = Math.min(s.block.number, Math.floor(before / 1_000_000));
  const lower = Number(s.client.chain.deployBlock); let rows = []; let start = end;
  for (let page = 0; page < 4 && end >= lower && rows.length < limit; page++) {
    start = Math.max(lower, end - 1_999);
    // `extra` adds rows a topic filter cannot select (e.g. batch events matched by owner ID) over
    // the same range, so they page with everything else.
    const [found, added] = await Promise.all([eventFacts(s, names, { ...options, fromBlock: start, toBlock: end }),
      extra ? extra({ fromBlock: start, toBlock: end }) : []]);
    rows.push(...[...found, ...added].filter(row => eventOrdinal(row) < before));
    end = start - 1;
  }
  rows.sort((a, b) => -compareLogs(a, b));
  // One log can expand to several rows (a batch's lanes share its position, and the cursor is a
  // log position), so a page never ends part-way through a log: keep the rest of that log's rows.
  const total = rows.length; let cut = Math.min(limit, total);
  if (total > limit) { const last = eventOrdinal(rows[limit - 1]); while (cut < total && eventOrdinal(rows[cut]) === last) cut++; }
  const more = total > cut; rows = rows.slice(0, cut);
  return { rows, nextCursor: more ? eventOrdinal(rows.at(-1)) : start > lower ? start * 1_000_000 : null };
}
export const eventOrdinal = row => Number(row.blockNumber) * 1_000_000 + Number(row.logIndex);
export async function activityRange(s, day, signal) {
  return s.client.dayRange(day, s, signal);
}
// A settlement can happen after its wall-clock day, so only the LOWER timestamp
// bound is valid. Indexed day topics and transaction anchors pick the actual
// settlement; never stop the search at the next midnight.
export async function settlementFacts(s, contract, names, day, { signal, player, filters } = {}) {
  const { fromBlock } = await activityRange(s, day, signal);
  return eventFacts(s, names, { contract, day, player, filters, fromBlock, signal });
}
export function feedPage(events, url, map = row => row) {
  const before = Number(url.searchParams.get('before') ?? url.searchParams.get('cursor') ?? Infinity);
  const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit') ?? 50)));
  const items = events.filter(row => row.blockNumber * 1_000_000 + row.logIndex < before).reverse().slice(0, limit + 1);
  const more = items.length > limit; const page = items.slice(0, limit);
  return { items: page.map(row => bigintJSON(map(row))), nextCursor: more ? page.at(-1).blockNumber * 1_000_000 + page.at(-1).logIndex : null };
}
